@media (max-width: 480px) {
    .tp-tr {
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
    }
    .tp-pn {
        width: 90vw !important;
        height: 72vh !important;
        max-height: 450px !important;
        min-height: 300px !important;
        padding: 16px !important;
        top: 40% !important;
        transform: translate(-50%, -40%) scale(0) translateZ(0) !important;
    }
    .tp-pn.active {
        transform: translate(-50%, -40%) scale(1) translateZ(0) !important;
    }
    .tp-close {
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        background: linear-gradient(145deg, rgba(220,38,38,0.3), rgba(35,45,60,0.7));
    }
    .tp-close::before {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: 50%;
        background: linear-gradient(145deg, rgba(220,38,38,0.5), rgba(35,45,60,0.8));
        box-shadow: 
            0 0 12px rgba(239, 68, 68, 0.6),
            0 0 24px rgba(252, 165, 165,0.3),
            inset 0 1px 0 rgba(255,255,255,0.1);
        opacity: 0;
        transition: opacity 0.2s cubic-bezier(0.25, 0.8, 0.25, 1);
        z-index: -1;
    }
    .tp-close:hover::before {
        opacity: 1;
    }
    .tp-close:hover {
        box-shadow: none;
    }
    .tp-tab {
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
        background: linear-gradient(145deg, rgba(15,20,35,0.6), rgba(10,15,25,0.5)) !important;
    }
    .tp-tab::before {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: 18px;
        background: linear-gradient(145deg, rgba(28,36,55,0.7), rgba(18,24,38,0.6));
        opacity: 0;
        transition: opacity 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
        z-index: -1;
    }
    .tp-tab::after {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: 18px;
        background: linear-gradient(145deg, rgba(79,163,255,0.2), rgba(120,100,220,0.18)), linear-gradient(145deg, rgba(28, 36, 55, 0.7), rgba(18, 24, 38, 0.6));
        box-shadow: 0 0 8px rgba(120,100,220,0.4), 0 0 16px rgba(79,163,255,0.2), inset 0 1px 0 rgba(255,255,255,0.1);
        opacity: 0;
        transition: opacity 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
        z-index: -1;
    }
    .tp-tab:hover::before {
        opacity: 1;
    }
    .tp-tab:hover {
        box-shadow: none;
    }
    .tp-tab.active::after {
        opacity: 1;
    }
    .tp-tab.active {
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
        box-shadow: none;
    }
    .tp-ct {
        height: calc(100% - 70px) !important;
        -webkit-overflow-scrolling: touch;
    }
    .tp-grid, .tp-scroll {
        grid-template-columns: 1fr;
    }
    .tp-scroll {
        -webkit-overflow-scrolling: touch;
    }
    .tp-btn,
    .tp-btn2,
    .tp-btn3,
    .tp-btn4 {
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        background: 
            radial-gradient(circle at 10% 95%, rgba(100,80,200,0.12), transparent 40%),
            linear-gradient(160deg, rgba(12,16,28,0.2), rgba(16,22,38,0.15));
        box-shadow: 
            0 0 6px rgba(160,180,200,0.35),
            0 4px 12px rgba(0,0,0,0.25),
            inset 0 1px 0 rgba(255,255,255,0.08);
    }
    .tp-btn::before,
    .tp-btn2::before,
    .tp-btn3::before,
    .tp-btn4::before {
        background: 
            radial-gradient(circle at 10% 95%, rgba(100,80,200,0.15), transparent 40%),
            linear-gradient(160deg, rgba(12,16,28,0.25), rgba(16,22,38,0.18));
        box-shadow: 
            0 0 8px rgba(160,180,200,0.45),
            0 6px 16px rgba(0,0,0,0.3),
            inset 0 1px 0 rgba(255,255,255,0.12);
    }
    .tp-btn:hover,
    .tp-btn2:hover,
    .tp-btn3:hover,
    .tp-btn4:hover {
        box-shadow: none;
    }
    .tp-btn::after,
    .tp-btn2::after,
    .tp-btn3::after,
    .tp-btn4::after {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: 12px;
        background: 
            radial-gradient(circle at 10% 95%, rgba(100,80,200,0.09), transparent 40%),
            linear-gradient(160deg, rgba(12,16,28,0.16), rgba(16,22,38,0.12));
        box-shadow: 
            0 0 4px rgba(160,180,200,0.3),
            0 2px 8px rgba(0,0,0,0.2),
            inset 0 1px 0 rgba(255,255,255,0.06);
        opacity: 0;
        transition: opacity 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
        z-index: -1;
        pointer-events: none;
    }
    .tp-btn:active::before,
    .tp-btn2:active::before,
    .tp-btn3:active::before,
    .tp-btn4:active::before {
        opacity: 0;
    }
    .tp-btn:active::after,
    .tp-btn2:active::after,
    .tp-btn3:active::after,
    .tp-btn4:active::after {
        opacity: 1;
    }
    .tp-btn:active,
    .tp-btn2:active,
    .tp-btn3:active,
    .tp-btn4:active {
        box-shadow: none;
    }
    .yw-master-control {
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
    }
    .yw-auto-textarea {
        -webkit-overflow-scrolling: touch;
    }
}
